	// Wait for container to start
	time.Sleep(2 * time.Second)

	// Verify container is running
	stdout, _, err = client.RunCommand(t.Context(), "docker ps --filter 'name=lifecycle' --format '{{.Names}}'")
	if err != nil {
		t.Fatalf("docker ps failed: %v", err)
