func TestAccStackResource_DeleteFile(t *testing.T) {
	t.Parallel()

	container := SetupSSHDockerContainer(t)

	config := internalssh.Config{
		Host:                  container.Host,
		Port:                  container.Port,
		User:                  container.User,
